async function obligations(f){const result={};for(const table of ['agreements','quote_acceptances','scope_entitlements','entitlement_versions','scope_allocations','allocation_plan_versions','allocation_plan_parts'])result[table]=(await client.query('SELECT to_jsonb(r)::text AS value FROM crest.'+table+' r WHERE business_id=$1 ORDER BY to_jsonb(r)::text COLLATE "C"',[f.business])).rows.map(row=>row.value);return result;}

function tabStorage(){const values=new Map();return {getItem:key=>values.get(key)??null,setItem:(key,value)=>{values.set(key,value);},removeItem:key=>{values.delete(key);}};}
