function retainedOriginal(f,kind,request,storage){
 const reference=kind==='quote.amendment.create'?quoteAmendmentDraftReference(request):quoteAmendmentSendReference(request),store=createPendingQuoteAmendmentStore(storage,kind);
 const pinned={schemaVersion:1,businessId:f.business,binding:randomBytes(32).toString('base64url'),reference};store.write(pinned);
 const encoded=JSON.stringify(pinned);assert(!encoded.includes('contentHash'));assert(!encoded.includes('expectedHash'));assert(!encoded.includes('expectedParentAcceptedHash'));assert(!encoded.includes('PRIVATE_SYNTHETIC'));assert(!encoded.includes('recipient'));assert(!encoded.includes('body'));assert(encoded.length<2048);
 return {store,pinned,open:()=>openPendingOriginalOperation(kind,storage,f.business)};
}
